package mesh

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
	"time"

	"openbear/node/mesh/transport"
)

// TestContract runs configs generated by the controller's own code
// (app/servers/mesh_config.py, through testdata/contract_configs.py) on real
// data plane processes, each in its own oblab- namespace on one bridge:
// relays r1 and r2 linked over UDP, then over TCP; m1, m2 and m3 entering
// over UDP, TCP and TLS; m1 and m2 linked directly; m3 a gateway with
// address translation for a LAN namespace. OBLAB_CONTRACT=1 enables it; it
// needs root and the repository's .venv.
func TestContract(t *testing.T) {
	if os.Getenv("OBLAB_CONTRACT") != "1" || os.Getuid() != 0 {
		t.Skip("set OBLAB_CONTRACT=1 and run as root")
	}
	self, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	wd, _ := os.Getwd()
	repo := filepath.Clean(filepath.Join(wd, "..", ".."))
	ids := []string{"r1", "r2", "m1", "m2", "m3"}
	ns := map[string]string{"br": "oblab-cbr", "lan": "oblab-clan"}
	for _, id := range ids {
		ns[id] = "oblab-c" + id
	}
	sh := func(args ...string) {
		t.Helper()
		if out, err := exec.Command(args[0], args[1:]...).CombinedOutput(); err != nil {
			t.Fatalf("%s: %v: %s", strings.Join(args, " "), err, out)
		}
	}
	in := func(id string, args ...string) (string, error) {
		out, err := exec.Command("ip", append([]string{"netns", "exec", ns[id]}, args...)...).CombinedOutput()
		return string(out), err
	}
	cleanup := func() {
		for _, n := range ns {
			exec.Command("ip", "netns", "del", n).Run()
		}
	}
	cleanup()
	linksLeft := rootLinksLeft(t, "obl", "obmesh")
	t.Cleanup(func() {
		cleanup()
		if out, _ := exec.Command("ip", "netns", "list").Output(); bytes.Contains(out, []byte("oblab-c")) {
			t.Errorf("namespaces left behind: %s", out)
		}
		linksLeft()
	})
	for _, n := range ns {
		sh("ip", "netns", "add", n)
		sh("ip", "-n", n, "link", "set", "lo", "up")
	}
	sh("ip", "-n", ns["br"], "link", "add", "br0", "type", "bridge")
	sh("ip", "-n", ns["br"], "link", "set", "br0", "up")
	underlay := map[string]string{}
	for i, id := range ids {
		port := "oblc" + id
		underlay[id] = fmt.Sprintf("10.97.0.%d", i+1)
		sh("ip", "link", "add", port, "netns", ns["br"], "type", "veth", "peer", "name", "obleth", "netns", ns[id])
		sh("ip", "-n", ns["br"], "link", "set", port, "master", "br0", "up")
		sh("ip", "-n", ns[id], "addr", "add", underlay[id]+"/24", "dev", "obleth")
		sh("ip", "-n", ns[id], "link", "set", "obleth", "up")
	}
	sh("ip", "link", "add", "obllan", "netns", ns["m3"], "type", "veth", "peer", "name", "obleth", "netns", ns["lan"])
	sh("ip", "-n", ns["m3"], "addr", "add", "10.98.0.1/24", "dev", "obllan")
	sh("ip", "-n", ns["m3"], "link", "set", "obllan", "up")
	sh("ip", "-n", ns["lan"], "addr", "add", "10.98.0.2/24", "dev", "obleth")
	sh("ip", "-n", ns["lan"], "link", "set", "obleth", "up")
	sh("ip", "netns", "exec", ns["m3"], "sysctl", "-qw", "net.ipv4.ip_forward=0")

	dirs, keys := map[string]string{}, map[string][4]string{}
	for _, id := range ids {
		dirs[id] = t.TempDir()
		wgPriv, wgPub := newKey(t)
		ctlPriv, ctlPub := newKey(t)
		keys[id] = [4]string{wgPub, ctlPub, testSignPub(id), testE2EPub(id)}
		os.MkdirAll(filepath.Join(dirs[id], "keys"), 0o700)
		os.WriteFile(filepath.Join(dirs[id], "keys", "wg.key"), []byte(wgPriv), 0o600)
		os.WriteFile(filepath.Join(dirs[id], "keys", "control.key"), []byte(ctlPriv), 0o600)
		writeTestKeys(t, dirs[id], id)
	}
	certs, err := transport.EnsureCertificate(filepath.Join(dirs["r2"], "tls"))
	if err != nil {
		t.Fatal(err)
	}

	addr := map[string]string{}
	generate := func(revision int, relayTransport string) {
		t.Helper()
		work := t.TempDir()
		input, _ := json.Marshal(map[string]any{"keys": keys, "ipv4": underlay, "relayTransport": relayTransport, "revision": revision, "configSchemas": ConfigSchemas(),
			"tlsFingerprint": map[string]string{"r2": certs.Active.FingerprintSHA256}})
		os.WriteFile(filepath.Join(work, "in.json"), input, 0o600)
		cmd := exec.Command(filepath.Join(repo, ".venv", "bin", "python"), "node/mesh/testdata/contract_configs.py",
			filepath.Join(work, "in.json"), filepath.Join(work, "out.json"))
		cmd.Dir = repo
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("controller config build: %v: %s", err, out)
		}
		var got struct {
			Configs map[string]json.RawMessage `json:"configs"`
			Errors  []map[string]any           `json:"errors"`
		}
		raw, _ := os.ReadFile(filepath.Join(work, "out.json"))
		if err := json.Unmarshal(raw, &got); err != nil {
			t.Fatal(err)
		}
		if len(got.Errors) > 0 {
			t.Fatalf("the controller refuses its own draft: %v", got.Errors)
		}
		for _, id := range ids {
			c, err := ParseConfig(got.Configs[id])
			if err != nil {
				t.Fatalf("the data plane refuses the controller's config for %s: %v\n%s", id, err, got.Configs[id])
			}
			addr[id] = c.Self.Address.String()
			path := filepath.Join(dirs[id], "config.json")
			os.WriteFile(path+".tmp", got.Configs[id], 0o600)
			if err := os.Rename(path+".tmp", path); err != nil {
				t.Fatal(err)
			}
		}
	}
	status := func(id string) Status {
		var s Status
		raw, _ := os.ReadFile(filepath.Join(dirs[id], "status.json"))
		json.Unmarshal(raw, &s)
		return s
	}
	waitFor := func(what string, ok func() bool) {
		t.Helper()
		for deadline := time.Now().Add(30 * time.Second); !ok(); time.Sleep(200 * time.Millisecond) {
			if time.Now().After(deadline) {
				t.Fatalf("timed out waiting for %s", what)
			}
		}
	}

	generate(1, "udp")
	procs := map[string]*exec.Cmd{}
	for _, id := range ids {
		log, _ := os.Create(filepath.Join(dirs[id], "mesh.log"))
		cmd := exec.Command("ip", "netns", "exec", ns[id], self, "-test.run", "^TestNetnsNode$", "-test.v")
		cmd.Env = append(os.Environ(), "OBLAB_MESH_DIR="+dirs[id])
		cmd.Stdout, cmd.Stderr = log, log
		if err := cmd.Start(); err != nil {
			t.Fatal(err)
		}
		procs[id] = cmd
	}
	t.Cleanup(func() {
		for id, cmd := range procs {
			cmd.Process.Signal(os.Interrupt)
			done := make(chan error, 1)
			go func() { done <- cmd.Wait() }()
			select {
			case <-done:
			case <-time.After(10 * time.Second):
				cmd.Process.Kill()
				t.Errorf("%s did not stop on SIGINT", id)
			}
		}
		if t.Failed() {
			for _, id := range ids {
				raw, _ := os.ReadFile(filepath.Join(dirs[id], "mesh.log"))
				st, _ := os.ReadFile(filepath.Join(dirs[id], "status.json"))
				t.Logf("%s log:\n%s\n%s status:\n%s", id, raw, id, st)
			}
		}
	})
	for _, id := range ids {
		waitFor(id+" ready", func() bool { s := status(id); return s.Ready && s.AppliedRevision == 1 })
	}

	ttl := regexp.MustCompile(`ttl=(\d+)`)
	ping := func(from, to string) (string, bool) {
		var out string
		var err error
		for try := 0; try < 3; try++ { // the first packet may wait for a handshake
			if out, err = in(from, "ping", "-c", "1", "-W", "2", to); err == nil {
				if m := ttl.FindStringSubmatch(out); m != nil {
					return m[1], true
				}
			}
		}
		return "", false
	}
	expectPing := func(from, to, wantTTL string) {
		t.Helper()
		target := to
		if a, ok := addr[to]; ok {
			target = a
		}
		got, ok := ping(from, target)
		if !ok || (wantTTL != "" && got != wantTTL) {
			t.Fatalf("%s ping %s: ok %v ttl %s, want ttl %s", from, to, ok, got, wantTTL)
		}
	}
	refused := func(from, to string) {
		t.Helper()
		target := to
		if a, ok := addr[to]; ok {
			target = a
		}
		if _, err := in(from, "ping", "-c", "1", "-W", "1", target); err == nil {
			t.Fatalf("%s reached %s, which no rule allows", from, to)
		}
	}
	connect := func(from, host string, port int) (string, bool) {
		out, err := in(from, "python3", "-I", "-c", fmt.Sprintf(`
import socket
s = socket.create_connection((%q, %d), timeout=2); print(s.recv(64).decode())`, host, port))
		return strings.TrimSpace(out), err == nil
	}
	serve := func(id, host string, port int) {
		cmd := exec.Command("ip", "netns", "exec", ns[id], "python3", "-I", "-c", fmt.Sprintf(`
import socket
s = socket.socket(); s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1); s.bind((%q, %d)); s.listen()
while True:
    c, peer = s.accept(); c.sendall(peer[0].encode()); c.close()
`, host, port))
		if err := cmd.Start(); err != nil {
			t.Fatal(err)
		}
		t.Cleanup(func() { cmd.Process.Kill(); cmd.Wait() })
	}

	reachability := func() {
		t.Helper()
		// Direct link: no relay hop either way. Through r1 only, and
		// through both relays, end to end: the relays forward the outer
		// packet and leave the one inside as it was sent.
		sent := status("m1").E2E.Sent
		forwarded := status("r1").Counters.Forwarded + status("r2").Counters.Forwarded
		expectPing("m1", "m2", "64")
		expectPing("m2", "m1", "64")
		expectPing("m1", "m3", "64")
		expectPing("m3", "m1", "64")
		expectPing("m2", "m3", "64")
		expectPing("m3", "m2", "64")
		waitFor("status to count the pings", func() bool {
			return status("m1").E2E.Sent > sent && status("r1").Counters.Forwarded+status("r2").Counters.Forwarded > forwarded
		})
		if got, ok := connect("m1", addr["m3"], 7000); !ok || got != addr["m1"] {
			t.Fatalf("m1 to m3:7000: %q %v", got, ok)
		}
		if got, ok := connect("m1", "10.98.0.2", 7100); !ok || got != "10.98.0.1" {
			t.Fatalf("m1 to the LAN behind m3: %q %v (want the gateway's address after translation)", got, ok)
		}
	}
	serve("m3", addr["m3"], 7000)
	serve("lan", "10.98.0.2", 7100)
	time.Sleep(300 * time.Millisecond)
	reachability()
	expectPing("m1", "10.98.0.2", "")
	if _, ok := connect("m2", addr["m3"], 7000); ok {
		t.Fatal("m2 reached m3:7000; only m1 may")
	}
	if _, ok := connect("m2", "10.98.0.2", 7100); ok {
		t.Fatal("m2 reached the LAN behind m3; only m1 may")
	}
	refused("m2", "10.98.0.2")
	refused("m1", "r1") // relays have no rules
	if s := status("m3"); s.Counters.DroppedACL == 0 {
		t.Fatalf("m3 counted no refusals: %+v", s.Counters)
	}
	transports := func(id string) map[string]string {
		out := map[string]string{}
		for _, p := range status(id).Peers {
			out[p.ID] = p.Transport
		}
		return out
	}
	if got := transports("r1"); got["r2"] != "udp" || got["m1"] != "udp" || got["m2"] != "tcp" {
		t.Fatalf("r1's transports %v", got)
	}
	if got := transports("r2"); got["m3"] != "tls" {
		t.Fatalf("r2's transports %v", got)
	}
	if got := status("r2").TLSCertificate; got != certs.Active.ID {
		t.Fatalf("r2 reports certificate %q, want %q", got, certs.Active.ID)
	}

	// The relay link moves to TCP online.
	generate(2, "tcp")
	for _, id := range ids {
		waitFor(id+" applying revision 2", func() bool { s := status(id); return s.AppliedRevision == 2 && s.Error == "" })
	}
	waitFor("r1 to reach r2 over tcp", func() bool { return transports("r1")["r2"] == "tcp" && transports("r2")["r1"] == "tcp" })
	reachability()
	refused("m2", "10.98.0.2")
}
